// slot 12: clear (flags: 1 colour, 2 depth, 4 stencil; the values from the base's clear block). The game also has
// a path that draws a quad instead (a viewport smaller than the target): G1. bgfx clears a view at its start, so a
// clear in the middle of a frame needs a new view (G1).
void bgfxContext::vfunc_12(int a0)
{
    ClearInfo* c = clearInfo();
    uint16_t f = 0;
    if (a0 & 1)
        f |= BGFX_CLEAR_COLOR;
    if (a0 & 2)
        f |= BGFX_CLEAR_DEPTH;
    if (a0 & 4)
        f |= BGFX_CLEAR_STENCIL;
    uint32_t rgba = (c->colour << 8) | (c->colour >> 24);      // D3DCOLOR 0xAARRGGBB -> 0xRRGGBBAA
    bgfx::setViewClear(0, f, rgba, c->depth, (uint8_t)c->stencil);
    if (m_display && m_display->m_initialised)
        bgfx::touch(0);
}
